#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_engine_one_door.py
# ─────────────────────────────────────────────────────────────
# ЛОМОТЬ 1 — ЕДИНЫЙ ДВИЖОК: одна дверь для бара.
# Кладёт studio/modules/trading/engine.py (мотор-дирижёр) и
# probe_engine.py (верстак для проверки, временный).
#
# Идемпотентно: повторный запуск перезапишет ровно эти два файла,
# создав .bak. Ничего живого в цеху НЕ трогает — только добавляет.
#
# Запуск из КОРНЯ репы:
#   python patch_engine_one_door.py
# Потом проверка на золоте (river-прогон, без LLM/терминала):
#   python -m studio.modules.trading.probe_engine \\
#          studio/modules/trading/test_data/XAUUSD_H4.csv XAUUSD H4
# ─────────────────────────────────────────────────────────────
import sys, py_compile, shutil, base64
from datetime import datetime
from pathlib import Path

MARKER = "ENGINE_ONE_DOOR_V1"
TRADING = Path("studio/modules/trading")

ENGINE_B64 = ""
PROBE_B64  = ""

def _write(path, b64):
    code = base64.b64decode(b64).decode("utf-8")
    if path.exists():
        bak = path.with_suffix(path.suffix + f".bak_{datetime.now():%Y%m%d_%H%M%S}")
        shutil.copy2(path, bak)
        tag = "уже стоял маркер" if MARKER in path.read_text(encoding="utf-8") else "БЕЗ маркера"
        print(f"  ↻ {path.name}: {tag} — бэкап {bak.name}, перезапишу")
    path.write_text(code, encoding="utf-8")
    py_compile.compile(str(path), doraise=True)
    print(f"  ✓ {path.name}: записан и скомпилирован")

def main():
    if not TRADING.exists():
        print(f"❌ Нет папки {TRADING} — запусти из КОРНЯ репы")
        sys.exit(1)
    print("─"*60)
    print("  ЛОМОТЬ 1 · ЕДИНЫЙ ДВИЖОК · одна дверь для бара")
    print("─"*60)
    _write(TRADING / "engine.py", ENGINE_B64)
    _write(TRADING / "probe_engine.py", PROBE_B64)
    print("─"*60)
    print("  ✅ Готово. Мотор в цеху, верстак рядом. Ничего живого не тронуто.")
    print("")
    print("  ПРОВЕРКА (river-прогон по золоту, без LLM и терминала):")
    print("  python -m studio.modules.trading.probe_engine \\")
    print("         studio/modules/trading/test_data/XAUUSD_H4.csv XAUUSD H4")
    print("─"*60)

if __name__ == "__main__":
    main()
